import React, { useState } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  InputAdornment,
  IconButton,
  Alert,
  CircularProgress
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  Mail,
  Lock
} from '@mui/icons-material';

// Main Login Form Component
const LoginForm = ({ 
  formData, 
  errors, 
  loading, 
  error, 
  onChange, 
  onSubmit, 
  onAutoFill, 
  onTogglePassword 
}) => {
  const [showPassword, setShowPassword] = useState(false);

  const handleChange = (e) => {
    onChange(e);
  };

  const handleSubmit = (e) => {
    onSubmit(e);
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
    onTogglePassword();
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        backgroundColor: '#ffffff',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontFamily: 'system-ui, -apple-system, sans-serif',
      }}
    >
      {/* Left Side - Blue Panel */}
      <Box
        sx={{
          width: '50%',
          height: '100vh',
          backgroundColor: '#3b82f6',
          display: { xs: 'none', md: 'flex' },
          alignItems: 'center',
          justifyContent: 'center',
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        <Box sx={{ textAlign: 'center', color: 'white', p: 4, zIndex: 1 }}>
          <Typography
            variant="h2"
            sx={{
              fontWeight: 700,
              mb: 2,
              fontSize: '3rem',
              lineHeight: 1.2,
            }}
          >
            Site Survey Tool
          </Typography>
          <Typography
            variant="h5"
            sx={{
              fontWeight: 400,
              mb: 4,
              fontSize: '1.25rem',
              opacity: 0.9,
            }}
          >
            ISP Site Survey Management System
          </Typography>
          <Box
            sx={{
              width: '200px',
              height: '200px',
              backgroundColor: 'rgba(255, 255, 255, 0.1)',
              borderRadius: '50%',
              mx: 'auto',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 4,
            }}
          >
            <Typography variant="h1" sx={{ fontSize: '4rem' }}>📐</Typography>
          </Box>
          <Typography
            variant="body1"
            sx={{
              fontSize: '1.1rem',
              opacity: 0.8,
              maxWidth: '400px',
              mx: 'auto',
            }}
          >
            Professional site survey management for ISP infrastructure
          </Typography>
        </Box>

        {/* Decorative circles */}
        <Box
          sx={{
            position: 'absolute',
            top: '-100px',
            right: '-100px',
            width: '300px',
            height: '300px',
            backgroundColor: 'rgba(255, 255, 255, 0.05)',
            borderRadius: '50%',
          }}
        />
        <Box
          sx={{
            position: 'absolute',
            bottom: '-150px',
            left: '-150px',
            width: '400px',
            height: '400px',
            backgroundColor: 'rgba(255, 255, 255, 0.03)',
            borderRadius: '50%',
          }}
        />
      </Box>

      {/* Right Side - Login Form */}
      <Box
        sx={{
          width: { xs: '100%', md: '50%' },
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          p: 4,
        }}
      >
        <Box sx={{ width: '100%', maxWidth: '400px' }}>
          <Typography
            variant="h4"
            sx={{
              fontWeight: 600,
              color: '#1f2937',
              mb: 1,
              fontSize: '1.875rem',
            }}
          >
            Welcome back
          </Typography>

          <Typography
            variant="body1"
            sx={{
              color: '#6b7280',
              mb: 6,
              fontSize: '1rem',
            }}
          >
            Please sign in to your account
          </Typography>

          {error && (
            <Alert 
              severity="error" 
              sx={{ 
                mb: 4,
                borderRadius: '8px',
                '& .MuiAlert-message': {
                  fontSize: '0.875rem',
                }
              }}
            >
              {error}
            </Alert>
          )}

          <Box component="form" onSubmit={handleSubmit} sx={{ width: '100%' }}>
            <TextField
              fullWidth
              name="email"
              type="email"
              placeholder="Email address"
              value={formData.email}
              onChange={handleChange}
              error={!!errors.email}
              helperText={errors.email}
              disabled={loading}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Mail sx={{ color: '#9ca3af', fontSize: 20 }} />
                  </InputAdornment>
                ),
                sx: {
                  height: '56px',
                  backgroundColor: '#f9fafb',
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '12px',
                    border: '1px solid #e5e7eb',
                    '& fieldset': {
                      borderColor: '#e5e7eb',
                      borderWidth: '1px',
                    },
                    '&:hover fieldset': {
                      borderColor: '#d1d5db',
                    },
                    '&.Mui-focused fieldset': {
                      borderColor: '#3b82f6',
                      borderWidth: '2px',
                    },
                  },
                },
              }}
              sx={{ mb: 3 }}
            />

            <TextField
              fullWidth
              name="password"
              type={showPassword ? 'text' : 'password'}
              placeholder="Password"
              value={formData.password}
              onChange={handleChange}
              error={!!errors.password}
              helperText={errors.password}
              disabled={loading}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Lock sx={{ color: '#9ca3af', fontSize: 20 }} />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={togglePasswordVisibility}
                      edge="end"
                      disabled={loading}
                      sx={{ color: '#9ca3af' }}
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
                sx: {
                  height: '56px',
                  backgroundColor: '#f9fafb',
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '12px',
                    border: '1px solid #e5e7eb',
                    '& fieldset': {
                      borderColor: '#e5e7eb',
                      borderWidth: '1px',
                    },
                    '&:hover fieldset': {
                      borderColor: '#d1d5db',
                    },
                    '&.Mui-focused fieldset': {
                      borderColor: '#3b82f6',
                      borderWidth: '2px',
                    },
                  },
                },
              }}
              sx={{ mb: 4 }}
            />

            <Button
              type="submit"
              fullWidth
              variant="contained"
              disabled={loading}
              sx={{
                backgroundColor: '#3b82f6',
                color: '#ffffff',
                py: 2.5,
                borderRadius: '12px',
                fontSize: '16px',
                fontWeight: 600,
                textTransform: 'none',
                boxShadow: '0 4px 6px -1px rgba(59, 130, 246, 0.3)',
                '&:hover': {
                  backgroundColor: '#2563eb',
                  boxShadow: '0 10px 15px -3px rgba(59, 130, 246, 0.4)',
                },
                '&:active': {
                  backgroundColor: '#1d4ed8',
                },
                '&.Mui-disabled': {
                  backgroundColor: '#e5e7eb',
                },
              }}
            >
              {loading ? (
                <CircularProgress size={24} color="inherit" />
              ) : (
                'Sign in'
              )}
            </Button>
          </Box>

          <Box sx={{ textAlign: 'center', mt: 6 }}>
            <Typography
              variant="body2"
              sx={{
                color: '#6b7280',
                fontSize: '0.875rem',
              }}
            >
              Don't have an account?{' '}
              <Box
                component="a"
                href="#"
                sx={{
                  color: '#3b82f6',
                  textDecoration: 'none',
                  fontWeight: 600,
                  '&:hover': {
                    textDecoration: 'underline',
                  },
                }}
              >
                Contact administrator
              </Box>
            </Typography>
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export default LoginForm;
